export default function read({ ticket, fieldId }) {
  const field = (ticket.raw.custom_fields || []).find((x) => x.id === fieldId);
  return {
    thread: typeof field?.value === "string" ? field.value : "",
    hasThread: !!field?.value,
    subject: ticket.subject || "",
  };
}

n_70c704dd25688b46.source:
export default function read({ thread }) {
  if (!thread) throw Error("Missing thread timestamp");
  return { thread };
}

n_455603491f4dbc14.source:
export default function field({ fieldId, ts }) {
  return { customFields: [{ id: fieldId, value: ts }] };
}
